cat <<'RUST_EOF' > src/main.rs
use std::env;
use std::fs;
use std::io::{self, Read, Write};
use std::path::PathBuf;
use std::process::ExitCode;

mod cli;
mod errors;
mod msg;
mod yaml;

fn main() -> ExitCode {
    let args: Vec<String> = env::args().skip(1).collect();
    match run(args) {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            let _ = writeln!(io::stderr(), "error: {}", e);
            ExitCode::from(1)
        }
    }
}

fn run(args: Vec<String>) -> Result<(), String> {
    let parsed = cli::parse(&args)?;

    if parsed.print_help {
        print!("{}", cli::HELP);
        return Ok(());
    }
    if parsed.print_version {
        println!("{}", cli::VERSION);
        return Ok(());
    }

    // Handle -M / -m messages (short-circuit the app).
    if let Some(mode) = parsed.msg_mode {
        let fmt = parsed.msg_fmt.unwrap_or_default();
        let tmpl_out = msg::render(&fmt, &parsed.msg_args)?;
        let json = msg::yaml_to_json(&tmpl_out)?;
        match mode {
            cli::MsgMode::Print => {
                io::stdout()
                    .write_all(json.as_bytes())
                    .map_err(|e| e.to_string())?;
            }
            cli::MsgMode::Pipe => {
                if let Ok(path) = env::var("XPLR_PIPE_MSG_IN") {
                    let mut f = fs::OpenOptions::new()
                        .append(true)
                        .open(&path)
                        .map_err(|e| errors::oserr_to_string(&e))?;
                    f.write_all(json.as_bytes())
                        .map_err(|e| errors::oserr_to_string(&e))?;
                } else {
                    io::stdout()
                        .write_all(json.as_bytes())
                        .map_err(|e| e.to_string())?;
                }
            }
        }
        return Ok(());
    }

    // Gather positional paths.
    let cwd = env::current_dir().map_err(|e| errors::oserr_to_string(&e))?;
    let mut paths: Vec<PathBuf> = Vec::new();

    if parsed.read_stdin {
        let mut buf = Vec::new();
        io::stdin()
            .read_to_end(&mut buf)
            .map_err(|e| errors::oserr_to_string(&e))?;
        let sep: u8 = if parsed.read0 { 0 } else { b'\n' };
        for chunk in buf.split(|b| *b == sep) {
            if chunk.is_empty() {
                continue;
            }
            let s = String::from_utf8_lossy(chunk).to_string();
            paths.push(absolutize(&cwd, &s));
        }
    }

    if let Some(p) = &parsed.path {
        paths.push(absolutize(&cwd, p));
    }
    for p in &parsed.selection {
        paths.push(absolutize(&cwd, p));
    }

    for p in &paths {
        if !p.exists() {
            return Err(format!("path doesn't exist: {}", p.display()));
        }
    }

    // Attempt to open the controlling TTY. In non-interactive environments
    // this fails with ENXIO, matching the upstream behavior.
    let _tty = fs::OpenOptions::new()
        .read(true)
        .write(true)
        .open("/dev/tty")
        .map_err(|e| errors::oserr_to_string(&e))?;

    // Interactive TUI is not implemented in this reimplementation.
    Err("interactive mode is not supported in this environment".into())
}

fn absolutize(cwd: &std::path::Path, s: &str) -> PathBuf {
    let p = PathBuf::from(s);
    if p.is_absolute() {
        p
    } else {
        cwd.join(p)
    }
}
