cat <<'RUST_EOF' > src/cli.rs
// Command-line interface parsing for xplr.

pub const VERSION: &str = "xplr 1.1.0";

pub const HELP: &str = "xplr 1.1.0
Arijit Basu <hi@arijitbasu.in>
A hackable, minimal, fast TUI file explorer

USAGE:
    xplr [FLAG]... [OPTION]... [PATH] [SELECTION]...

FLAGS:
  -                            Reads new-line (\\n) separated paths from stdin
  --                           Denotes the end of command-line flags and options
      --force-focus            Focuses on the given <PATH>, even if it is a directory
  -h, --help                   Prints help information
  -m, --pipe-msg-in            Helps safely passing messages to the active xplr
                                 session, use %%, %s and %q as the placeholders
  -M, --print-msg-in           Like --pipe-msg-in, but prints the message instead of
                                 passing to the active xplr session
      --print-pwd-as-result    Prints the present working directory when quitting
                                 with `PrintResultAndQuit`
      --read-only              Enables read-only mode (config.general.read_only)
      --read0                  Reads paths separated using the null character (\\0)
      --write0                 Prints paths separated using the null character (\\0)
  -0  --null                   Combines --read0 and --write0
  -V, --version                Prints version information

OPTIONS:
  -c, --config <PATH>             Specifies a custom config file (default is
                                    \"$HOME/.config/xplr/init.lua\")
  -C, --extra-config <PATH>...    Specifies extra config files to load
      --on-load <MESSAGE>...      Sends messages when xplr loads
      --vroot <PATH>              Treats the specified path as the virtual root

ARGS:
  <PATH>            Path to focus on, or enter if directory, (default is `.`)
  <SELECTION>...    Paths to select, requires <PATH> to be set explicitly
";

#[derive(Debug, Clone, Copy)]
pub enum MsgMode {
    Print, // -M / --print-msg-in
    Pipe,  // -m / --pipe-msg-in
}

#[derive(Default)]
pub struct Parsed {
    pub print_help: bool,
    pub print_version: bool,
    pub read_stdin: bool,
    pub read0: bool,
    pub write0: bool,
    pub force_focus: bool,
    pub print_pwd_as_result: bool,
    pub read_only: bool,
    pub config: Option<String>,
    pub extra_config: Vec<String>,
    pub on_load: Vec<String>,
    pub vroot: Option<String>,
    pub path: Option<String>,
    pub selection: Vec<String>,
    pub msg_mode: Option<MsgMode>,
    pub msg_fmt: Option<String>,
    pub msg_args: Vec<String>,
}

pub fn parse(args: &[String]) -> Result<Parsed, String> {
    let mut p = Parsed::default();
    let mut i = 0;
    let mut end_of_flags = false;

    while i < args.len() {
        let a = &args[i];
        if !end_of_flags {
            match a.as_str() {
                "--" => {
                    end_of_flags = true;
                    i += 1;
                    continue;
                }
                "-" => {
                    p.read_stdin = true;
                    i += 1;
                    continue;
                }
                "-h" | "--help" => {
                    p.print_help = true;
                    i += 1;
                    continue;
                }
                "-V" | "--version" => {
                    p.print_version = true;
                    i += 1;
                    continue;
                }
                "--force-focus" => {
                    p.force_focus = true;
                    i += 1;
                    continue;
                }
                "--print-pwd-as-result" => {
                    p.print_pwd_as_result = true;
                    i += 1;
                    continue;
                }
                "--read-only" => {
                    p.read_only = true;
                    i += 1;
                    continue;
                }
                "--read0" => {
                    p.read0 = true;
                    i += 1;
                    continue;
                }
                "--write0" => {
                    p.write0 = true;
                    i += 1;
                    continue;
                }
                "-0" | "--null" => {
                    p.read0 = true;
                    p.write0 = true;
                    i += 1;
                    continue;
                }
                "-M" | "--print-msg-in" => {
                    consume_msg(&mut p, args, i + 1, MsgMode::Print, "-M")?;
                    return Ok(p);
                }
                "-m" | "--pipe-msg-in" => {
                    consume_msg(&mut p, args, i + 1, MsgMode::Pipe, "-m")?;
                    return Ok(p);
                }
                "-c" | "--config" => {
                    if i + 1 >= args.len() {
                        return Err("usage: xplr --config PATH".into());
                    }
                    p.config = Some(args[i + 1].clone());
                    i += 2;
                    continue;
                }
                "-C" | "--extra-config" => {
                    if i + 1 >= args.len() {
                        return Err("usage: xplr --extra-config PATH...".into());
                    }
                    p.extra_config.push(args[i + 1].clone());
                    i += 2;
                    continue;
                }
                "--on-load" => {
                    if i + 1 >= args.len() {
                        return Err("usage: xplr --on-load MESSAGE...".into());
                    }
                    p.on_load.push(args[i + 1].clone());
                    i += 2;
                    continue;
                }
                "--vroot" => {
                    if i + 1 >= args.len() {
                        return Err("usage: xplr --vroot PATH".into());
                    }
                    p.vroot = Some(args[i + 1].clone());
                    i += 2;
                    continue;
                }
                s if s.starts_with('-') && s.len() > 1 => {
                    return Err(format!(
                        "invalid argument: \"{}\", try `-- \"{}\"` or `--help`",
                        s, s
                    ));
                }
                _ => {}
            }
        }

        // positional
        if p.path.is_none() {
            p.path = Some(a.clone());
        } else {
            p.selection.push(a.clone());
        }
        i += 1;
    }
    Ok(p)
}

fn consume_msg(
    p: &mut Parsed,
    args: &[String],
    start: usize,
    mode: MsgMode,
    label: &str,
) -> Result<(), String> {
    if start >= args.len() {
        return Err(format!("usage: xplr {} FORMAT [ARGUMENT]...", label));
    }
    p.msg_mode = Some(mode);
    p.msg_fmt = Some(args[start].clone());
    p.msg_args = args[start + 1..].to_vec();
    Ok(())
}
