// Implements the -M / -m message rendering:
//   * Template substitution (%%, %s, %q) on the FORMAT string.
//   * Parsing the rendered YAML as a xplr message (enum variant).
//   * Re-serializing as compact JSON.

use crate::yaml;

pub fn render(template: &str, values: &[String]) -> Result<String, String> {
    let bytes = template.as_bytes();
    let mut out = String::with_capacity(template.len());
    let mut i = 0;
    let mut value_idx = 0;
    while i < bytes.len() {
        let c = bytes[i];
        if c != b'%' {
            out.push(c as char);
            i += 1;
            continue;
        }
        // We are at a '%'.
        if i + 1 >= bytes.len() {
            return Err("xplr -m: template ended with incomplete placeholder".into());
        }
        let n = bytes[i + 1];
        let col = i + 1; // column number in message is 1-based index of '%'
        match n {
            b'%' => {
                out.push('%');
                i += 2;
            }
            b's' => {
                if value_idx >= values.len() {
                    return Err(format!(
                        "xplr -m: placeholder missing value at column {}",
                        col
                    ));
                }
                out.push_str(&values[value_idx]);
                value_idx += 1;
                i += 2;
            }
            b'q' => {
                if value_idx >= values.len() {
                    return Err(format!(
                        "xplr -m: placeholder missing value at column {}",
                        col
                    ));
                }
                out.push_str(&json_quote(&values[value_idx]));
                value_idx += 1;
                i += 2;
            }
            other => {
                return Err(format!(
                    "xplr -m: invalid placeholder '%{}' at column {}, use one of '%s' or '%q', or escape it using '%%'",
                    other as char, col
                ));
            }
        }
    }
    if value_idx < values.len() {
        return Err(
            "xplr -m: too many positional values, not enough positional placeholders".into(),
        );
    }
    Ok(out)
}

fn json_quote(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\x08' => out.push_str("\\b"),
            '\x0c' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                out.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

pub fn yaml_to_json(input: &str) -> Result<String, String> {
    let v = yaml::parse(input).map_err(|e| e.into_message())?;
    let json = to_json(&v);
    validate_variant(&v, input)?;
    Ok(json)
}

fn validate_variant(v: &yaml::Value, _src: &str) -> Result<(), String> {
    // For tagged messages the YAML value is either:
    //   - a plain scalar whose text is a variant name (unit variant), OR
    //   - a single-key mapping whose key is a variant name (newtype/struct).
    let (name, is_unit) = match v {
        yaml::Value::String(s) => (s.clone(), true),
        yaml::Value::Map(entries) if entries.len() == 1 => {
            let (k, _) = &entries[0];
            let key = match k {
                yaml::Value::String(s) => s.clone(),
                other => to_json(other),
            };
            (key, false)
        }
        _ => {
            // Unknown shape: report as the stringified value.
            (to_json(v), true)
        }
    };
    if !VARIANTS.iter().any(|n| *n == name.as_str()) {
        let list = variants_list();
        let col = name.len() + if is_unit { 1 } else { 3 };
        return Err(format!(
            "unknown variant `{}`, expected one of {} at line 1 column {}",
            name, list, col
        ));
    }
    Ok(())
}

fn variants_list() -> String {
    let mut s = String::new();
    for (idx, v) in VARIANTS.iter().enumerate() {
        if idx > 0 {
            s.push_str(", ");
        }
        s.push('`');
        s.push_str(v);
        s.push('`');
    }
    s
}

fn to_json(v: &yaml::Value) -> String {
    match v {
        yaml::Value::Null => "null".into(),
        yaml::Value::Bool(b) => if *b { "true".into() } else { "false".into() },
        yaml::Value::Number(n) => n.clone(),
        yaml::Value::String(s) => json_quote(s),
        yaml::Value::Seq(items) => {
            let mut out = String::from("[");
            for (i, it) in items.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                out.push_str(&to_json(it));
            }
            out.push(']');
            out
        }
        yaml::Value::Map(entries) => {
            let mut out = String::from("{");
            for (i, (k, v)) in entries.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                let ks = match k {
                    yaml::Value::String(s) => json_quote(s),
                    other => json_quote(&to_json(other)),
                };
                out.push_str(&ks);
                out.push(':');
                out.push_str(&to_json(v));
            }
            out.push('}');
            out
        }
    }
}

