// Minimal single-line YAML parser sufficient for xplr message payloads.
// Supports:
//   - plain scalars (bare words, numbers, bools, null)
//   - double-quoted strings with common escape sequences
//   - single-quoted strings
//   - flow sequences `[a, b, c]`
//   - flow mappings `{a: b, c: d}`
//   - simple block mapping `Key: value` (single-pair, single-line)

#[derive(Debug, Clone)]
pub enum Value {
    Null,
    Bool(bool),
    Number(String),
    String(String),
    Seq(Vec<Value>),
    Map(Vec<(Value, Value)>),
}

#[derive(Debug)]
pub struct Error {
    message: String,
}

impl Error {
    pub fn into_message(self) -> String {
        self.message
    }
}

pub fn parse(input: &str) -> Result<Value, Error> {
    let bytes = input.as_bytes();
    let mut p = Parser { bytes, pos: 0 };
    p.skip_ws();
    let v = p.parse_node(None)?;
    p.skip_ws();
    // trailing characters are ignored to match lenient YAML behavior
    Ok(v)
}

struct Parser<'a> {
    bytes: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn peek(&self) -> Option<u8> {
        self.bytes.get(self.pos).copied()
    }

    fn skip_ws(&mut self) {
        while let Some(c) = self.peek() {
            if c == b' ' || c == b'\t' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn parse_node(&mut self, stop: Option<&[u8]>) -> Result<Value, Error> {
        self.skip_ws();
        match self.peek() {
            None => Ok(Value::Null),
            Some(b'{') => self.parse_flow_map(),
            Some(b'[') => self.parse_flow_seq(),
            Some(b'"') => {
                let s = self.parse_double_quoted()?;
                self.skip_ws();
                // Could still be "key: value" with a quoted key.
                if self.peek() == Some(b':') {
                    self.pos += 1;
                    self.skip_ws();
                    let v = self.parse_node(stop)?;
                    return Ok(Value::Map(vec![(Value::String(s), v)]));
                }
                Ok(Value::String(s))
            }
            Some(b'\'') => {
                let s = self.parse_single_quoted()?;
                self.skip_ws();
                if self.peek() == Some(b':') {
                    self.pos += 1;
                    self.skip_ws();
                    let v = self.parse_node(stop)?;
                    return Ok(Value::Map(vec![(Value::String(s), v)]));
                }
                Ok(Value::String(s))
            }
            _ => self.parse_plain(stop),
        }
    }

    fn parse_flow_seq(&mut self) -> Result<Value, Error> {
        self.pos += 1; // [
        let mut items = Vec::new();
        loop {
            self.skip_ws();
            if self.peek() == Some(b']') {
                self.pos += 1;
                return Ok(Value::Seq(items));
            }
            let v = self.parse_flow_node()?;
            items.push(v);
            self.skip_ws();
            match self.peek() {
                Some(b',') => {
                    self.pos += 1;
                }
                Some(b']') => {
                    self.pos += 1;
                    return Ok(Value::Seq(items));
                }
                Some(c) => {
                    return Err(self.err(format!(
                        "unexpected character '{}' in flow sequence",
                        c as char
                    )))
                }
                None => return Err(self.err("unterminated flow sequence".into())),
            }
        }
    }

    fn parse_flow_map(&mut self) -> Result<Value, Error> {
        self.pos += 1; // {
        let mut entries = Vec::new();
        loop {
            self.skip_ws();
            if self.peek() == Some(b'}') {
                self.pos += 1;
                return Ok(Value::Map(entries));
            }
            let k = self.parse_flow_key()?;
            self.skip_ws();
            if self.peek() != Some(b':') {
                return Err(self.err("expected ':' in flow mapping".into()));
            }
            self.pos += 1;
            self.skip_ws();
            let v = self.parse_flow_node()?;
            entries.push((k, v));
            self.skip_ws();
            match self.peek() {
                Some(b',') => {
                    self.pos += 1;
                }
                Some(b'}') => {
                    self.pos += 1;
                    return Ok(Value::Map(entries));
                }
                Some(c) => {
                    return Err(self.err(format!(
                        "unexpected character '{}' in flow mapping",
                        c as char
                    )))
                }
                None => return Err(self.err("unterminated flow mapping".into())),
            }
        }
    }

    fn parse_flow_key(&mut self) -> Result<Value, Error> {
        match self.peek() {
            Some(b'"') => Ok(Value::String(self.parse_double_quoted()?)),
            Some(b'\'') => Ok(Value::String(self.parse_single_quoted()?)),
            _ => self.parse_plain_scalar(&[b':', b',', b'}', b']']),
        }
    }

    fn parse_flow_node(&mut self) -> Result<Value, Error> {
        self.skip_ws();
        match self.peek() {
            Some(b'{') => self.parse_flow_map(),
            Some(b'[') => self.parse_flow_seq(),
            Some(b'"') => Ok(Value::String(self.parse_double_quoted()?)),
            Some(b'\'') => Ok(Value::String(self.parse_single_quoted()?)),
            _ => self.parse_plain_scalar(&[b',', b'}', b']']),
        }
    }

    fn parse_double_quoted(&mut self) -> Result<String, Error> {
        self.pos += 1;
        let mut out = String::new();
        while let Some(c) = self.peek() {
            if c == b'"' {
                self.pos += 1;
                return Ok(out);
            }
            if c == b'\\' {
                self.pos += 1;
                let esc = self.peek().ok_or_else(|| self.err("bad escape".into()))?;
                self.pos += 1;
                match esc {
                    b'"' => out.push('"'),
                    b'\\' => out.push('\\'),
                    b'n' => out.push('\n'),
                    b'r' => out.push('\r'),
                    b't' => out.push('\t'),
                    b'0' => out.push('\0'),
                    b'b' => out.push('\x08'),
                    b'f' => out.push('\x0c'),
                    b'/' => out.push('/'),
                    other => out.push(other as char),
                }
            } else {
                out.push(c as char);
                self.pos += 1;
            }
        }
        Err(self.err("unterminated string".into()))
    }

    fn parse_single_quoted(&mut self) -> Result<String, Error> {
        self.pos += 1;
        let mut out = String::new();
        while let Some(c) = self.peek() {
            if c == b'\'' {
                // '' is an escaped quote.
                if self.bytes.get(self.pos + 1) == Some(&b'\'') {
                    out.push('\'');
                    self.pos += 2;
                    continue;
                }
                self.pos += 1;
                return Ok(out);
            }
            out.push(c as char);
            self.pos += 1;
        }
        Err(self.err("unterminated string".into()))
    }

    fn parse_plain(&mut self, stop: Option<&[u8]>) -> Result<Value, Error> {
        // Read a plain scalar. If followed by `:`, interpret as a mapping.
        let default_stop: &[u8] = &[];
        let stop = stop.unwrap_or(default_stop);
        let start = self.pos;
        while let Some(c) = self.peek() {
            if c == b':' {
                // check lookahead: YAML requires ': ' or ':' at EOL for mapping key delim
                let next = self.bytes.get(self.pos + 1);
                if next.map_or(true, |n| *n == b' ' || *n == b'\t') {
                    break;
                }
            }
            if stop.contains(&c) {
                break;
            }
            if c == b'\n' || c == b'\r' {
                break;
            }
            self.pos += 1;
        }
        let raw = &self.bytes[start..self.pos];
        let text = std::str::from_utf8(raw)
            .map_err(|e| self.err(e.to_string()))?
            .trim_end_matches(&[' ', '\t'][..])
            .to_string();

        if self.peek() == Some(b':') {
            // Consume the colon and following whitespace.
            self.pos += 1;
            self.skip_ws();
            // Value (rest of line).
            let v = self.parse_node(None)?;
            return Ok(Value::Map(vec![(scalar_from_text(&text), v)]));
        }
        Ok(scalar_from_text(&text))
    }

    fn parse_plain_scalar(&mut self, stops: &[u8]) -> Result<Value, Error> {
        let start = self.pos;
        while let Some(c) = self.peek() {
            if stops.contains(&c) {
                break;
            }
            if c == b'\n' || c == b'\r' {
                break;
            }
            self.pos += 1;
        }
        let raw = &self.bytes[start..self.pos];
        let text = std::str::from_utf8(raw)
            .map_err(|e| self.err(e.to_string()))?
            .trim_end_matches(&[' ', '\t'][..])
            .to_string();
        Ok(scalar_from_text(&text))
    }

    fn err(&self, msg: String) -> Error {
        Error {
            message: format!("xplr -m: yaml: {} at column {}", msg, self.pos + 1),
        }
    }
}

fn scalar_from_text(text: &str) -> Value {
    if text.is_empty() || text == "~" || text.eq_ignore_ascii_case("null") {
        return Value::Null;
    }
    if text == "true" || text == "True" || text == "TRUE" {
        return Value::Bool(true);
    }
    if text == "false" || text == "False" || text == "FALSE" {
        return Value::Bool(false);
    }
    if is_number(text) {
        return Value::Number(text.to_string());
    }
    Value::String(text.to_string())
}

fn is_number(s: &str) -> bool {
    let s = s.trim();
    if s.is_empty() {
        return false;
    }
    let bytes = s.as_bytes();
    let mut i = 0;
    if bytes[0] == b'+' || bytes[0] == b'-' {
        i += 1;
    }
    let mut has_digit = false;
    let mut has_dot = false;
    let mut has_exp = false;
    while i < bytes.len() {
        let c = bytes[i];
        match c {
            b'0'..=b'9' => has_digit = true,
            b'.' if !has_dot && !has_exp => has_dot = true,
            b'e' | b'E' if has_digit && !has_exp => {
                has_exp = true;
                if i + 1 < bytes.len() && (bytes[i + 1] == b'+' || bytes[i + 1] == b'-') {
                    i += 1;
                }
            }
            _ => return false,
        }
        i += 1;
    }
    has_digit
}
